#include <queue>
#include <vector>
#include <iostream>

void safe_access(std::priority_queue<int>& pq) {
    if (!pq.empty()) { // Mandatory check
        int max_val = pq.top();
        std::cout << "Top: " << max_val << std::endl;
        pq.pop();
    } else {
        std::cerr << "Error: Queue is empty.\n";
    }

